insert into public.official_translation_keys(translation_key) values ('landmarks.statueOfLiberty.name'),('landmarks.statueOfLiberty.description'),('landmarks.statueOfLiberty.alt'),('officialPostcards.statueOfLiberty.name'),('officialPostcards.statueOfLiberty.description'),('officialPostcards.statueOfLiberty.alt') on conflict do nothing;
