insert into public.official_asset_versions(asset_id,version,source,status,packaged_path,mime_type,width,height,byte_size,alt_text_key,is_decorative,author,metadata) select a.id,1,'packaged','active',v.path,'image/webp',v.width,v.height,v.bytes,v.alt_key,false,'DUIF · OpenAI ImageGen',v.metadata from (values ('landmark.statueOfLiberty.artwork','/assets/landmarks/statue-of-liberty.webp',256,256,17916,'landmarks.statueOfLiberty.alt',jsonb_build_object('kind','landmarkArtwork','catalogKey','landmark.statue-of-liberty','artDirection','postalWatercolorSticker','provenance',jsonb_build_object('tool','OpenAI ImageGen','origin','AI-assisted original illustration'))),('postcard.landmark.statueOfLiberty.front','/assets/postcards/landmarks/statue-of-liberty.webp',1200,800,112256,'officialPostcards.statueOfLiberty.alt',jsonb_build_object('kind','postcardArtwork','landmarkCatalogKey','landmark.statue-of-liberty','provenance',jsonb_build_object('tool','OpenAI ImageGen','origin','AI-assisted original illustration')))) v(asset_key,path,width,height,bytes,alt_key,metadata) join public.official_assets a on a.asset_key=v.asset_key where not exists(select 1 from public.official_asset_versions e where e.asset_id=a.id and e.version=1);
